import pandas as pd
import numpy as np


def _sig_part(v):
    """COALESCE(v, '') then RTRIM (trailing whitespace stripped)."""
    if v is None:
        s = ""
    elif isinstance(v, float) and pd.isna(v):
        s = ""
    elif pd.isna(v) if not isinstance(v, (list, dict)) else False:
        s = ""
    else:
        s = str(v)
    return s.rstrip()


def _signature(city, tier):
    return _sig_part(city) + "|" + _sig_part(tier)


def run(inputs: dict) -> dict:
    dim = inputs["DIM_MEMBER"].copy()
    stg = inputs["STG_MEMBER"].copy()

    # Preserve column order / set up working structures
    dim_cols = ["member_id", "city", "tier", "eff_start_date", "eff_end_date", "is_current"]
    for c in dim_cols:
        if c not in dim.columns:
            dim[c] = None

    # Work with a list of row-dicts for easy in-place mutation + append
    rows = dim.to_dict("records")

    # Build quick index: member_id -> index of current row (is_current == 1)
    # Only one current row expected per member_id, but be defensive.
    def find_current_idx(member_id):
        for i, r in enumerate(rows):
            if r["member_id"] == member_id and _is_true_current(r.get("is_current")):
                return i
        return None

    def _is_true_current(v):
        if v is None:
            return False
        if isinstance(v, float) and pd.isna(v):
            return False
        try:
            return int(v) == 1
        except (ValueError, TypeError):
            return False

    new_rows = []

    for _, s in stg.iterrows():
        member_id = s["member_id"]
        s_city = s["city"]
        s_tier = s["tier"]
        s_update_date = s["update_date"]

        cur_idx = find_current_idx(member_id)

        if cur_idx is None:
            new_rows.append({
                "member_id": member_id,
                "city": s_city,
                "tier": s_tier,
                "eff_start_date": s_update_date,
                "eff_end_date": None,
                "is_current": 1,
            })
        else:
            cur = rows[cur_idx]
            sig_s = _signature(s_city, s_tier)
            sig_c = _signature(cur.get("city"), cur.get("tier"))

            if sig_s != sig_c:
                # close prior current row
                rows[cur_idx] = {
                    **cur,
                    "eff_end_date": s_update_date,
                    "is_current": 0,
                }
                new_rows.append({
                    "member_id": member_id,
                    "city": s_city,
                    "tier": s_tier,
                    "eff_start_date": s_update_date,
                    "eff_end_date": None,
                    "is_current": 1,
                })
            # else: no-op, current row untouched

    all_rows = rows + new_rows

    out = pd.DataFrame(all_rows, columns=dim_cols)

    return {"dim_member_out": out}
